#!/usr/bin/env python3

import binascii

def decode_nibble(encoded_value, offset):
    # Convert the encoded value back to original nibble
    decoded = int(encoded_value) - offset

    # Convert values 11-16 back to hex letters a-f
    if decoded >= 11:
        return "abcdef"[decoded - 11]
    return str(decoded)

def decode_bytes(encoded_text, offset=9133337):
    nibble_len = len(str(offset)) + 1  # Since offset starts with 9
    decoded = ""

    # Process encoded text in chunks of nibble_len
    for i in range(0, len(encoded_text), nibble_len * 2):
        try:
            # Get two nibbles (one byte)
            nibble1 = encoded_text[i:i + nibble_len]
            nibble2 = encoded_text[i + nibble_len:i + 2*nibble_len]

            # Decode each nibble
            decoded_byte = decode_nibble(nibble1, offset) + decode_nibble(nibble2, offset)
            decoded += decoded_byte
        except:
            continue

    return decoded

def main():
    # Read the encoded file
    with open('/home/ctfplayer/ctf_files/Challenge/DES2Bytes.enc', 'r') as f:
        encoded = f.read().strip()

    # Decode the text
    decoded_hex = decode_bytes(encoded)
    print("Decoded hex:", decoded_hex[:100])  # Print first 100 chars

    try:
        # Convert hex to bytes
        decoded_bytes = binascii.unhexlify(decoded_hex)
        print("\nFirst few bytes:", decoded_bytes[:50].hex())
    except Exception as e:
        print("Error converting to bytes:", e)

if __name__ == "__main__":
    main()

