from Crypto.Cipher import DES
import base64
import binascii
import sys

# List of known DES weak keys
WEAK_KEYS = [
    0x0101010101010101,
    0xFEFEFEFEFEFEFEFE,
    0xE0E0E0E0F1F1F1F1,
    0x1F1F1F1F0E0E0E0E,
    0x011F011F010E010E,
    0x1F011F010E010E01,
    0x01E001E001F101F1,
    0xE001E001F101F101,
    0x01FE01FE01FE01FE,
    0xFE01FE01FE01FE01,
    0x1FE01FE00EF10EF1,
    0xE01FE01FF10EF10E,
    0x1FFE1FFE0EFE0EFE,
    0xFE1FFE1FFE0EFE0E,
    0xE0FEE0FEF1FEF1FE,
    0xFEE0FEE0FEF1FEF1
]

def hex_to_bytes(hex_str):
    return binascii.unhexlify(hex_str)

def int_to_bytes(n):
    return n.to_bytes(8, byteorder='big')

def decrypt_des_ofb(ciphertext, key, iv):
    try:
        cipher = DES.new(key, DES.MODE_OFB, iv=iv)
        return cipher.decrypt(ciphertext)
    except Exception as e:
        return None

def try_all_key_pairs(ciphertext, iv):
    results = []
    for key1 in WEAK_KEYS:
        for key2 in WEAK_KEYS:
            try:
                # Convert integer keys to bytes
                key1_bytes = int_to_bytes(key1)
                key2_bytes = int_to_bytes(key2)

                # First DES decryption
                intermediate = decrypt_des_ofb(ciphertext, key1_bytes, iv)
                if intermediate is None:
                    continue

                # Second DES decryption
                plaintext = decrypt_des_ofb(intermediate, key2_bytes, iv)
                if plaintext is None:
                    continue

                # Check if result looks like readable text
                if all(32 <= c <= 126 or c in (10, 13) for c in plaintext):
                    results.append({
                        'key1': hex(key1),
                        'key2': hex(key2),
                        'plaintext': plaintext.decode('ascii', errors='ignore')
                    })
            except Exception as e:
                continue
    return results

def main():
    # Fixed IV as specified
    iv = b'13371337'

    # Read encrypted files
    try:
        with open('/home/ctfplayer/ctf_files/DES2Bytes.enc', 'rb') as f:
            des2bytes_enc = f.read()

        with open('/home/ctfplayer/ctf_files/FLAG.enc', 'rb') as f:
            flag_enc = f.read()

        # Test with first 32 bytes first
        print("Testing with first 32 bytes of DES2Bytes.enc...")
        sample_results = try_all_key_pairs(des2bytes_enc[:32], iv)

        if sample_results:
            print("\nFound potential matches with sample:")
            for result in sample_results:
                print(f"\nKey1: {result['key1']}")
                print(f"Key2: {result['key2']}")
                print(f"Plaintext: {result['plaintext']}")

            # If sample worked, try with full files
            print("\nTrying full DES2Bytes.enc file...")
            full_results = try_all_key_pairs(des2bytes_enc, iv)

            if full_results:
                print("\nFull file decryption results:")
                for result in full_results:
                    print(f"\nKey1: {result['key1']}")
                    print(f"Key2: {result['key2']}")
                    print(f"Plaintext: {result['plaintext']}")

                # Try the same keys with FLAG.enc
                print("\nTrying FLAG.enc with successful keys...")
                for result in full_results:
                    key1 = int_to_bytes(int(result['key1'], 16))
                    key2 = int_to_bytes(int(result['key2'], 16))

                    intermediate = decrypt_des_ofb(flag_enc, key1, iv)
                    flag_plaintext = decrypt_des_ofb(intermediate, key2, iv)

                    if flag_plaintext:
                        print(f"\nPossible flag found:")
                        print(flag_plaintext.decode('ascii', errors='ignore'))

        else:
            print("No valid decryption found with sample. Please check keys and data.")

    except FileNotFoundError as e:
        print(f"Error: Could not find input files: {e}")
    except Exception as e:
        print(f"Error during decryption: {e}")

